import { useId } from "react";

export interface DatePickerProps {
  label: string;
  value: string;
  onChange: (value: string) => void;
}

export default function DatePicker({
  label,
  value,
  onChange,
}: DatePickerProps) {
  const inputId = useId();

  return (
    <div>
      <label htmlFor={inputId}>{label}</label>
      <input
        id={inputId}
        type="date"
        value={value}
        onChange={(event) => onChange(event.target.value)}
      />
    </div>
  );
}
